// src/pages/Pedidos.jsx
import { useEffect, useState } from "react";
import { api } from "../services/api";
import { ChefHat } from "lucide-react";

export default function Pedidos() {
  const [pedidos, setPedidos] = useState([]);

  useEffect(() => {
    cargarPedidos();
    const interval = setInterval(cargarPedidos, 5000);
    return () => clearInterval(interval);
  }, []);

  const cargarPedidos = async () => {
    try {
      const res = await api.get("/pedidos/");
      setPedidos(res.filter(p => p.estado === "confirmado" || p.estado === "borrador"));
    } catch (err) {
      console.log(err);
    }
  };

  const enviarACocina = async (pedidoId) => {
    await api.post(`/pedidos/${pedidoId}/enviar-cocina/`);
    cargarPedidos();
  };

  return (
    <div className="p-8 min-h-screen bg-gray-100">
      <h1 className="text-5xl font-bold text-center mb-10 text-gray-800">
        PEDIDOS DEL MESERO
      </h1>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {pedidos.length === 0 ? (
          <div className="col-span-full text-center text-3xl text-gray-600 mt-20">
            No hay pedidos pendientes
          </div>
        ) : (
          pedidos.map((pedido) => (
            <div key={pedido.id} className="bg-white rounded-2xl shadow-2xl p-8 border-4 border-yellow-400">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-3xl font-bold">Mesa {pedido.mesa?.numero || "?"}</h2>
                <span className="text-xl bg-yellow-500 px-4 py-2 rounded-full">
                  {pedido.estado.toUpperCase()}
                </span>
              </div>

              <div className="space-y-3 mb-8">
                {pedido.detalles?.map((item) => (
                  <div key={item.id} className="flex justify-between text-lg">
                    <span>{item.cantidad}x {item.producto.nombre}</span>
                  </div>
                ))}
              </div>

              {pedido.estado === "confirmado" && (
                <button
                  onClick={() => enviarACocina(pedido.id)}
                  className="w-full bg-orange-600 hover:bg-orange-500 text-white text-2xl font-bold py-6 rounded-xl flex items-center justify-center gap-3 transform hover:scale-105 transition"
                >
                  <ChefHat size={40} />
                  ENVIAR A COCINA
                </button>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}
